#!/usr/bin/env tsx
/**
 * Census-driven LEGI Archive Ingestion for French Law MCP.
 *
 * Reads data/census.json (generated by census.ts) and parses ALL texts
 * from the extracted DILA LEGI open data corpus. Produces seed JSON
 * files in data/seed/ and updates census.json with ingestion results.
 *
 * This is the FULL CORPUS ingestion — not limited to a handful of codes.
 *
 * Issue #97 invariants:
 *   - the corpus is resolved at runtime (newest global + every incremental
 *     delta from the DILA index), NEVER a hardcoded archive;
 *   - the census and the extraction must carry the SAME source stamp;
 *   - article versions are selected by [DATE_DEBUT, DATE_FIN) validity,
 *     not by longest content;
 *   - seeds are stamped with the source identity and per-provision validity;
 *   - partial ingestion FAILS LOUD: every dropped target is enumerated and
 *     the process exits non-zero. Never present a partial corpus as complete.
 *
 * Data source: https://echanges.dila.gouv.fr/OPENDATA/LEGI/
 * Licence: Licence Ouverte v2.0
 *
 * Usage:
 *   npm run ingest:legi                        # Full census-driven ingestion
 *   npm run ingest:legi -- --archive /path.tgz # Use specific archive (no deltas, loud)
 *   npm run ingest:legi -- --extracted /path    # Use already-extracted directory (marker required)
 *   npm run ingest:legi -- --codes-only         # Only ingest codes (skip TNC)
 *   npm run ingest:legi -- --limit 10           # Limit number of texts to ingest
 *   npm run ingest:legi -- --allow-unstamped    # accept an unprovable corpus (loud)
 */

import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import { parseLegiXml, type ParsedArticle } from './lib/parser.js';
import { resolveCorpus, type ExtractIdentity } from './lib/legi-acquire.js';
import { selectArticles } from './lib/version-select.js';
import { resolveTextDir } from './lib/text-path.js';
import { classifyZeroProvisionText, type ZeroProvisionStats } from './lib/ingest-outcome.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const SEED_DIR = path.resolve(__dirname, '../data/seed');
const DATA_DIR = path.resolve(__dirname, '../data');
const CENSUS_PATH = path.join(DATA_DIR, 'census.json');

// ---------------------------------------------------------------------------
// Census types
// ---------------------------------------------------------------------------

interface CensusLaw {
  id: string;
  title: string;
  title_en: string | null;
  identifier: string;        // LEGITEXT or JORFTEXT ID
  url: string | null;
  status: string;
  category: string;
  classification: string;
  classification_reason: string;
  ingested: boolean;
  provision_count: number;
  ingestion_date: string | null;
}

interface CensusSourceArchive {
  base: string;
  base_stamp: string;
  deltas_applied: number;
  last_delta: string | null;
  source_stamp: string;
  acquired_at: string;
}

interface CensusFile {
  schema_version: string;
  jurisdiction: string;
  jurisdiction_name: string;
  portal: string;
  census_date: string;
  agent: string;
  source_archive?: CensusSourceArchive;
  summary: {
    total_laws: number;
    total_provisions: number;
    ingestable: number;
    ocr_needed: number;
    inaccessible: number;
    excluded: number;
  };
  laws: CensusLaw[];
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

interface CliArgs {
  archive?: string;
  extracted?: string;
  codesOnly: boolean;
  limit?: number;
  allowUnstamped: boolean;
}

function parseArgs(): CliArgs {
  const args = process.argv.slice(2);
  let archive: string | undefined;
  let extracted: string | undefined;
  let codesOnly = false;
  let limit: number | undefined;
  let allowUnstamped = false;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--archive' && args[i + 1]) { archive = args[i + 1]; i++; }
    else if (args[i] === '--extracted' && args[i + 1]) { extracted = args[i + 1]; i++; }
    else if (args[i] === '--codes-only') { codesOnly = true; }
    else if (args[i] === '--limit' && args[i + 1]) { limit = parseInt(args[i + 1], 10); i++; }
    else if (args[i] === '--allow-unstamped') { allowUnstamped = true; }
  }
  return { archive, extracted, codesOnly, limit, allowUnstamped };
}

// ---------------------------------------------------------------------------
// LEGI archive helpers
// ---------------------------------------------------------------------------

function walkXmlFiles(dir: string): string[] {
  const results: string[] = [];
  if (!fs.existsSync(dir)) return results;
  const walk = (d: string) => {
    let entries;
    try { entries = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const fp = path.join(d, entry.name);
      if (entry.isDirectory()) walk(fp);
      else if (entry.name.endsWith('.xml') && entry.name.startsWith('LEGIARTI')) results.push(fp);
    }
  };
  walk(dir);
  return results;
}

// ---------------------------------------------------------------------------
// Parse a single text from the extracted archive
// ---------------------------------------------------------------------------

interface ParsedProvision {
  provision_ref: string;
  chapter?: string;
  section: string;
  title: string;
  content: string;
  valid_from?: string;
  valid_to?: string;
}

interface ParsedLaw {
  documentId: string;
  title: string;
  titleEn: string | null;
  shortName: string | null;
  status: string;
  url: string | null;
  description: string | null;
  provisions: ParsedProvision[];
  /** Article-level evidence for zero-provision classification (issue #97). */
  stats: ZeroProvisionStats;
}

function parseTextDirectory(textDir: string, censusEntry: CensusLaw, today: string): ParsedLaw {
  const articleFiles = walkXmlFiles(textDir);

  const candidates: ParsedArticle[] = [];
  let fileErrors = 0;
  let parseErrors = 0;
  let articleNodesSeen = 0;

  for (const xmlFile of articleFiles) {
    try {
      const xmlContent = fs.readFileSync(xmlFile, 'utf-8');
      const result = parseLegiXml(xmlContent);
      articleNodesSeen += result.articleNodesSeen;
      parseErrors += result.errors.length;
      candidates.push(...result.articles);
    } catch {
      fileErrors++;
    }
  }

  // Validity-aware version selection per article number (issue #97: the old
  // keep-longest dedupe could serve an outdated longer version forever).
  const nonEmpty = candidates.filter((a) => a.content.trim().length > 0);
  const { selected, droppedExpiredNums } = selectArticles(nonEmpty, today);

  const provisions: ParsedProvision[] = selected.map((article) => ({
    provision_ref: `art${article.normalizedNum}`,
    section: article.normalizedNum,
    title: article.title,
    content: article.content,
    ...(article.dateDebut ? { valid_from: article.dateDebut } : {}),
    ...(article.dateFin ? { valid_to: article.dateFin } : {}),
  }));

  return {
    documentId: censusEntry.id,
    title: censusEntry.title,
    titleEn: censusEntry.title_en,
    shortName: null,
    status: censusEntry.status,
    url: censusEntry.url,
    description: null,
    provisions,
    stats: {
      articleFiles: articleFiles.length,
      fileErrors,
      parseErrors,
      articleNodesSeen,
      vigueurVersions: candidates.length,
      nonEmptyVigueurVersions: nonEmpty.length,
      expiredOnlyNums: droppedExpiredNums.length,
    },
  };
}

// ---------------------------------------------------------------------------
// Seed writers
// ---------------------------------------------------------------------------

function writeSeed(law: ParsedLaw, identity: ExtractIdentity, retrievedAt: string): void {
  fs.mkdirSync(SEED_DIR, { recursive: true });
  const seed = {
    id: law.documentId,
    type: 'statute',
    title: law.title,
    title_en: law.titleEn,
    short_name: law.shortName,
    status: law.status === 'repealed' ? 'repealed' : law.status === 'amended' ? 'amended' : 'in_force',
    url: law.url,
    description: law.description,
    provisions: law.provisions,
    _ingest: {
      retrieved_at: retrievedAt,
      source_base: identity.base,
      source_last_delta: identity.deltas_applied.at(-1) ?? null,
      source_stamp: identity.source_stamp,
    },
  };
  const fp = path.join(SEED_DIR, `${law.documentId}.json`);
  fs.writeFileSync(fp, JSON.stringify(seed, null, 2), 'utf-8');
}

