// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

interface DroppedTarget {
  id: string;
  identifier: string;
  reason: string;
}

async function main(): Promise<void> {
  const { archive, extracted, codesOnly, limit, allowUnstamped } = parseArgs();

  console.log('=== French Law MCP — Census-Driven LEGI Ingestion ===\n');

  // Load census
  if (!fs.existsSync(CENSUS_PATH)) {
    console.error(`Census file not found: ${CENSUS_PATH}`);
    console.error('Run census first: npx tsx scripts/census.ts');
    process.exit(1);
  }

  const census: CensusFile = JSON.parse(fs.readFileSync(CENSUS_PATH, 'utf-8'));
  console.log(`Census loaded: ${census.laws.length} texts`);

  // Acquire the corpus and verify it is the SAME corpus the census saw.
  const { extractDir, identity } = await resolveCorpus({ archive, extracted, allowUnstamped });
  const today = new Date().toISOString().split('T')[0];

  if (!census.source_archive) {
    console.error(
      'Census carries no source_archive stamp — it predates source-identity stamping (issue #97) ' +
        'and its corpus version is unprovable. Re-run: npx tsx scripts/census.ts',
    );
    process.exit(1);
  }
  if (identity.source_stamp === 'unstamped' || census.source_archive.source_stamp === 'unstamped') {
    console.warn(
      'WARNING: unstamped corpus and/or census — census/extraction consistency CANNOT be verified.',
    );
  } else if (census.source_archive.source_stamp !== identity.source_stamp) {
    console.error(
      `Census was taken from source stamp ${census.source_archive.source_stamp} but the extraction ` +
        `is at ${identity.source_stamp}. Re-run census against the current corpus: npx tsx scripts/census.ts`,
    );
    process.exit(1);
  }

  // Filter to ingestable texts.
  // Default: codes + lois + ordonnances (primary legislation)
  // --codes-only: only codes
  let targets = census.laws.filter(l => l.classification === 'ingestable');
  if (codesOnly) {
    targets = targets.filter(l => l.category === 'code');
    console.log(`Codes-only mode: ${targets.length} codes`);
  } else {
    // Default: codes + lois + ordonnances (primary consolidated legislation)
    const PRIMARY_CATEGORIES = new Set(['code', 'loi', 'ordonnance']);
    targets = targets.filter(l => PRIMARY_CATEGORIES.has(l.category));
    console.log(`Primary legislation mode: ${targets.length} texts (codes + lois + ordonnances)`);
  }
  if (limit) {
    targets = targets.slice(0, limit);
    console.log(`Limited to ${limit} texts`);
  }

  console.log(`Texts to ingest: ${targets.length}\n`);

  // Clear old seed files (except eu-references.json)
  if (fs.existsSync(SEED_DIR)) {
    const oldFiles = fs.readdirSync(SEED_DIR).filter(f =>
      f.endsWith('.json') && f !== 'eu-references.json'
    );
    for (const f of oldFiles) {
      fs.unlinkSync(path.join(SEED_DIR, f));
    }
    console.log(`Cleared ${oldFiles.length} old seed files`);
  }
  fs.mkdirSync(SEED_DIR, { recursive: true });

  // Ingest each text
  const results: Array<{ id: string; provisions: number }> = [];
  const dropped: DroppedTarget[] = [];
  const outOfForce: DroppedTarget[] = [];
  let totalProvisions = 0;
  let processed = 0;
  let totalFileErrors = 0;
  let totalExpiredNums = 0;
  const retrievedAt = new Date().toISOString();

  for (const entry of targets) {
    processed++;

    // Resolve the text directory from the LEGITEXT/JORFTEXT identifier.
    // LEGITEXT-keyed texts live under code_en_vigueur OR TNC_en_vigueur
    // (consolidated lois/ordonnances) — the old single-prefix mapping
    // silently dropped the latter (73 texts in the 2026-06 corpus).
    const { dir: textDir, checked } = resolveTextDir(extractDir, entry.identifier);

    if (textDir === null) {
      dropped.push({
        id: entry.id,
        identifier: entry.identifier,
        reason: `directory not found in extracted corpus (checked: ${checked.join(', ')})`,
      });
      continue;
    }

    const law = parseTextDirectory(textDir, entry, today);
    totalFileErrors += law.stats.fileErrors;
    totalExpiredNums += law.stats.expiredOnlyNums;

    if (law.provisions.length === 0) {
      // Article-level evidence decides whether this is an EXPECTED exclusion
      // (text wholly out of force upstream) or a real ingestion anomaly. The
      // text-level TEXTE_VERSION status cannot be trusted for this (DILA keeps
      // VIGUEUR text metadata on abrogated texts).
      const outcome = classifyZeroProvisionText(law.stats);
      const target = { id: entry.id, identifier: entry.identifier, reason: outcome.reason };
      if (outcome.kind === 'out_of_force') {
        outOfForce.push(target);
      } else {
        dropped.push(target);
      }
      continue;
    }

    writeSeed(law, identity, retrievedAt);
    results.push({ id: law.documentId, provisions: law.provisions.length });
    totalProvisions += law.provisions.length;

    // Update census entry
    entry.ingested = true;
    entry.provision_count = law.provisions.length;
    entry.ingestion_date = today;

    if (processed % 50 === 0 || processed === targets.length) {
      console.log(`  [${processed}/${targets.length}] ${entry.id}: ${law.provisions.length} provisions (running total: ${totalProvisions})`);
    }
  }

  // Write EU references and manual seeds
  writeEuReferences();
  writeManualSeeds();

  // Update census with ingestion results
  census.summary.total_provisions = totalProvisions;
  fs.writeFileSync(CENSUS_PATH, JSON.stringify(census, null, 2), 'utf-8');
  console.log(`\nUpdated census: ${CENSUS_PATH}`);

  // Summary
  console.log('\n=== Ingestion Summary ===');
  console.log(`Source corpus: ${identity.base} + ${identity.deltas_applied.length} deltas (stamp ${identity.source_stamp})`);
  console.log(`Processed: ${processed} texts`);
  console.log(`Ingested: ${results.length} texts with provisions`);
  console.log(`Excluded as out of force: ${outOfForce.length}`);
  console.log(`Dropped (anomalies): ${dropped.length}`);
  console.log(`Total provisions: ${totalProvisions}`);
  console.log(`Article files unreadable/unparseable: ${totalFileErrors}`);
  console.log(`Article numbers excluded (no in-force version): ${totalExpiredNums}`);

  // Top 10 largest
  results.sort((a, b) => b.provisions - a.provisions);
  console.log('\nTop 10 largest:');
  for (const r of results.slice(0, 10)) {
    console.log(`  ${r.id}: ${r.provisions} provisions`);
  }

  console.log('\n+ 2 manual seeds (LPM 2024-2030 cyber, NIS 2 transposition)');

  // Expected exclusions: texts the article-level evidence proves wholly out
  // of force. Enumerated for auditability — these are NOT failures.
  if (outOfForce.length > 0) {
    console.log(`\n=== EXCLUDED OUT-OF-FORCE TEXTS (${outOfForce.length}) — expected, not failures ===`);
    for (const d of outOfForce) {
      console.log(`  ${d.id} (${d.identifier}): ${d.reason}`);
    }
  }

  // FAIL LOUD on partial ingestion (issue #97 / no-silent-fallbacks): every
  // anomalous target is enumerated and the exit code is non-zero. A non-zero
  // exit means DO NOT ship this seed set without investigating the drops.
  if (dropped.length > 0) {
    console.error(`\n=== DROPPED TARGETS (${dropped.length}) — PARTIAL INGESTION, exit 1 ===`);
    for (const d of dropped) {
      console.error(`  ${d.id} (${d.identifier}): ${d.reason}`);
    }
    console.error('\nSeeds for successful texts were written, but the corpus is INCOMPLETE.');
    process.exit(1);
  }

  console.log('\nNext step: npm run build:db');
}

main().catch(err => {
  console.error('LEGI ingestion failed:', err);
  process.exit(1);
});
